DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.tenants WHERE tenant_code='QUALISPHERE-SANDBOX' AND status='inactive') THEN RAISE EXCEPTION 'Expected isolated sandbox clone'; END IF; END $guard$;
CREATE POLICY "Allow reading evidence bucket" ON storage.objects FOR SELECT TO authenticated USING ((select clone_runtime.allowed_user()) AND ((bucket_id = 'evidence'::text)));
CREATE POLICY "Allow uploads to evidence bucket" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((select clone_runtime.allowed_user()) AND ((bucket_id = 'evidence'::text)));
CREATE POLICY "Audit evidence tenant delete" ON storage.objects FOR DELETE TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'audit-evidence'::text) AND qualisphere_can_access_audit_evidence_object(name))));
CREATE POLICY "Audit evidence tenant insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'audit-evidence'::text) AND qualisphere_can_access_audit_evidence_object(name))));
CREATE POLICY "Audit evidence tenant read" ON storage.objects FOR SELECT TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'audit-evidence'::text) AND qualisphere_can_access_audit_evidence_object(name))));
CREATE POLICY "Audit evidence tenant update" ON storage.objects FOR UPDATE TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'audit-evidence'::text) AND qualisphere_can_access_audit_evidence_object(name)))) WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'audit-evidence'::text) AND qualisphere_can_access_audit_evidence_object(name))));
CREATE POLICY "Authenticated users delete CAPA evidence" ON storage.objects FOR DELETE TO authenticated USING ((select clone_runtime.allowed_user()) AND ((bucket_id = 'capa-evidence'::text)));
CREATE POLICY "Authenticated users read CAPA evidence" ON storage.objects FOR SELECT TO authenticated USING ((select clone_runtime.allowed_user()) AND ((bucket_id = 'capa-evidence'::text)));
CREATE POLICY "Authenticated users upload CAPA evidence" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((select clone_runtime.allowed_user()) AND ((bucket_id = 'capa-evidence'::text)));
CREATE POLICY "Controlled documents tenant delete" ON storage.objects FOR DELETE TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'controlled-documents'::text) AND qualisphere_can_access_controlled_document_storage_object(name))));
CREATE POLICY "Controlled documents tenant insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'controlled-documents'::text) AND (name ~~ 'tenant/%'::text) AND qualisphere_can_access_controlled_document_storage_object(name))));
CREATE POLICY "Controlled documents tenant read" ON storage.objects FOR SELECT TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'controlled-documents'::text) AND qualisphere_can_access_controlled_document_storage_object(name))));
CREATE POLICY "Controlled documents tenant update" ON storage.objects FOR UPDATE TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'controlled-documents'::text) AND qualisphere_can_access_controlled_document_storage_object(name)))) WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'controlled-documents'::text) AND (name ~~ 'tenant/%'::text) AND qualisphere_can_access_controlled_document_storage_object(name))));
CREATE POLICY "supplier document tenant delete" ON storage.objects FOR DELETE TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'supplier-documents'::text) AND qualisphere_can_access_supplier_document_storage_object(name))));
CREATE POLICY "supplier document tenant insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'supplier-documents'::text) AND qualisphere_can_access_supplier_document_storage_object(name))));
CREATE POLICY "supplier document tenant read" ON storage.objects FOR SELECT TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'supplier-documents'::text) AND qualisphere_can_access_supplier_document_storage_object(name))));
CREATE POLICY "supplier document tenant update" ON storage.objects FOR UPDATE TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'supplier-documents'::text) AND qualisphere_can_access_supplier_document_storage_object(name)))) WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'supplier-documents'::text) AND qualisphere_can_access_supplier_document_storage_object(name))));
CREATE POLICY "training_completion_evidence_read" ON storage.objects FOR SELECT TO authenticated USING ((select clone_runtime.allowed_user()) AND (((bucket_id = 'training-completion-evidence'::text) AND qualisphere_can_access_training_evidence(name, false))));
CREATE POLICY "training_completion_evidence_upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((select clone_runtime.allowed_user()) AND (((bucket_id = 'training-completion-evidence'::text) AND qualisphere_can_access_training_evidence(name, true))));

